    <component
      :is="inline && link ? 'a' : 'span'"
      v-bind="inline && link ? { href: logo.url, target: '_blank', rel: 'noopener' } : {}"
      class="project-affiliation-logo"
      :class="`project-affiliation-logo--${affiliation}`"
    >
      <img class="project-logo-light" :src="logo.src" :alt="logo.name">
      <img class="project-logo-dark" :src="logo.darkSrc" :alt="logo.name">
    </component>
  </span>
</template>

<script>
const affiliations = {
  pwc: { name: 'PwC', url: 'https://www.pwc.com.hk/', src: '/assets/img/PwC.svg', darkSrc: '/assets/img/pwc-logo-dark.svg' },
  hsbc: { name: 'HSBC', url: 'https://www.hsbc.com/', src: '/assets/img/hsbc.svg', darkSrc: '/assets/img/hsbc-logo-dark.svg' },
  hku: { name: 'The University of Hong Kong', url: 'https://www.hku.hk/', src: '/assets/img/hku-logo.svg', darkSrc: '/assets/img/hku-logo-dark.svg' },
};

export default {
  name: 'ProjectAffiliation',
  props: {
    affiliation: { type: String, required: true },
    inline: { type: Boolean, default: false },
    link: { type: Boolean, default: true },
  },
  computed: {
    logo() { return affiliations[this.affiliation]; },
  },
};
</script>

